// Lọc tin hợp kênh (tiền đời thường) + lấy tin mới nhất chưa làm.
// TODO: thay 'seen' bằng đọc DB/Sheet để nhớ tin đã làm.
const KEYWORDS = ['lãi suất','vay','mua nhà','vàng','kim cương','thuế','tiết kiệm','đầu cơ','ngân hàng','bất động sản','tạm ứng'];
const items = $input.all().map(i => i.json);
const pick = items.find(it => {
  const t = ((it.title||'') + ' ' + (it.contentSnippet||'')).toLowerCase();
  return KEYWORDS.some(k => t.includes(k));
}) || items[0];
return [{ json: { title: pick.title, link: pick.link, summary: pick.contentSnippet || '', pubDate: pick.pubDate || '' } }];

